CONDITION_REFS = ['__cond_building_fine_light__', '__cond_building_wear_light__', '__cond_building_wear_moderate__', '__cond_building_dirt_light__', '__cond_building_faded_light__', '__cond_building_repair_light__', '__cond_building_decay_light__', '__cond_building_damage_light__']
PARTS = ['massing', 'walls', 'roof', 'openings', 'ornament']

def build(final=None):
    G = {}
    for k, v in PART_COMMON.items(): G['bld_' + k] = v
    G['bld_type_name'] = list(TYPES)
    G['bld_condition'] = CONDITION_REFS
    for t, art in TYPES.items(): G['bld_type_%s' % slug(t)] = [art]
    G['bld_type'] = ['__bld_type_%s__' % slug(t) for t in TYPES]
    entries = {'style': [], 'vern': []}
    for grp, raw in (('style', STYLES), ('vern', VERN)):
        for row in raw:
            k, label, mass, walls, roof, opens, orn, pal = row.split('|')
            pre = 'bld_%s_%s_' % ('s' if grp == 'style' else 'v', k)
            G[pre + 'massing'] = P(mass); G[pre + 'walls'] = P(walls); G[pre + 'roof'] = P(roof); G[pre + 'openings'] = P(opens); G[pre + 'ornament'] = P(orn); G[pre + 'palette'] = P(pal)
            lead = 'A %s' if True else ''
            G[pre + 'prompt'] = ['A building in the %s manner: %s. For the walls, __%swalls__. For the roof, __%sroof__. For the openings, __%sopenings__. For the ornament, __%sornament__. The colours are __%spalette__. The foundation is __bld_foundation__, and the entrance is __bld_entrance__. It stands behind __bld_boundary__, with __bld_garden__.' % (label, '__%smassing__' % pre, pre, pre, pre, pre, pre)]
            G[pre + 'short'] = ['__%smassing__ in the %s manner, with __%swalls__, __%sroof__ and __%sopenings__.' % (pre, label, pre, pre, pre)]
            G[pre + 'full'] = ['__%sprompt__ A detail is __bld_roof_detail__. Another is __bld_cladding_extra__. The building is __bld_wealth__, and it is __bld_age__. Its condition is shown by __bld_condition__. A small sign by the door says __bld_sign_text__.' % pre]
            G[pre + 'scene'] = ['__%sfull__ __setting_conditions_any__' % pre]
            entries[grp].append(pre)
    for grp, lst in entries.items():
        name = 'style' if grp == 'style' else 'vern'
        for suf in ('prompt', 'short', 'full', 'scene'): G['bld_%s_%s' % (name, suf)] = ['__%s%s__' % (p, suf) for p in lst]
        G['bld_%s_names' % name] = [r.split('|')[1] for r in (STYLES if grp == 'style' else VERN)]
    for suf in ('prompt', 'short', 'full', 'scene'): G['bld_' + suf] = ['__bld_style_%s__' % suf, '__bld_vern_%s__' % suf]
    G['bld_blend_prompt'] = ['__bld_type__, blending two traditions. The massing follows the __bld_vern_names__ tradition and the walls follow the __bld_style_names__ tradition. It stands behind __bld_boundary__, with __bld_garden__. The building is __bld_wealth__, and it is __bld_age__.']
    G['v74_arch_entry_points'] = ['bld_prompt', 'bld_short', 'bld_full', 'bld_scene', 'bld_style_prompt', 'bld_style_full', 'bld_vern_prompt', 'bld_vern_full', 'bld_blend_prompt']
    return G
